export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-0.2, 0.47, -0.11));
  camera.alpha = 2.25;
  camera.lowerAlphaLimit = 2.25;
  camera.upperAlphaLimit = 2.25;
  camera.beta = 1.46;
  camera.lowerBetaLimit = 1.1;
  camera.upperBetaLimit = 1.68;
  camera.radius = 2.567;
  camera.lowerRadiusLimit = 2.567;
  camera.upperRadiusLimit = 2.567;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 100;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.3;

  var dirLight = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(0.36, -0.5, -0.79), scene);
  dirLight.position = new BABYLON.Vector3(-6.14, 24, 46.37);
  dirLight.diffuse = BABYLON.Color3.FromHexString("#FFFFFF");
  dirLight.intensity = 1;
  dirLight.shadowMaxZ = 300;

  var ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 6, height: 6 }, scene);
  ground.receiveShadows = true;

  const material = new BABYLON.StandardMaterial("groundMaterial", scene);
  ground.material = material;

  function clampColor(color, maxValue) {
    const maxRGB = Math.max(color.r, color.g, color.b);
    if (maxRGB > maxValue) {
      const scale = maxValue / maxRGB;
      return new BABYLON.Color4(color.r * scale, color.g * scale, color.b * scale, color.a);
    }
    return color;
  }

  function calculateDiffuseColor(clearColor, lightIntensity) {
    const baseAdjustmentFactor = 1.25;
    const intensityAdjustment = 1 / lightIntensity;
    const finalAdjustmentFactor = baseAdjustmentFactor * intensityAdjustment;

    return new BABYLON.Color3(
      Math.min(clearColor.r * finalAdjustmentFactor, 1),
      Math.min(clearColor.g * finalAdjustmentFactor, 1),
      Math.min(clearColor.b * finalAdjustmentFactor, 1)
    );
  }

  const initialClearColor = BABYLON.Color4.FromHexString("#BA4747FF");
  scene.clearColor = clampColor(initialClearColor, 200 / 255);

  const lightIntensity = dirLight.intensity;

  scene.registerBeforeRender(function () {
    const clampedClearColor = clampColor(scene.clearColor, 200 / 255);
    scene.clearColor = clampedClearColor;

    const calculatedDiffuseColor = calculateDiffuseColor(clampedClearColor, lightIntensity);
    material.diffuseColor = calculatedDiffuseColor;
  });

  function generateRandomColor(maxValue) {
    let max = maxValue / 255;
    return new BABYLON.Color4(Math.random() * max, Math.random() * max, Math.random() * max, 1);
  }

  let targetColor = new BABYLON.Color4(0.75, 0.27, 0.27, 1);
  let currentColor = new BABYLON.Color4(0, 0, 0, 1);
  let step = 0.01;
  let rootMesh;
  let neckTN;
  let antennaTN;
  let screenMat;

  scene.registerBeforeRender(() => {
    currentColor = BABYLON.Color4.Lerp(currentColor, targetColor, step);
    scene.clearColor = currentColor;

    let distance = Math.sqrt(
      Math.pow(currentColor.r - targetColor.r, 2) +
        Math.pow(currentColor.g - targetColor.g, 2) +
        Math.pow(currentColor.b - targetColor.b, 2) +
        Math.pow(currentColor.a - targetColor.a, 2)
    );

    if (distance < 0.01) {
      targetColor = generateRandomColor(200);
    }

    if (screenMat) {
      screenMat.albedoColor = new BABYLON.Color3(targetColor.r, targetColor.g, targetColor.b);
    }
  });

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "robot_television.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.normalizeToUnitCube(true);

    neckTN = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "robot_rig:Head")[0];
    antennaTN = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "robot_rig:Antenna")[0];
    antennaTN.setParent(neckTN);

    document.addEventListener("mousemove", function (e) {
      var mousecoords = getMousePos(e);

      if (neckTN) {
        moveJoint(mousecoords, neckTN, 50);
      }
    });

    let shadowGenerator_D = new BABYLON.ShadowGenerator(1024, dirLight);
    shadowGenerator_D.usePercentageCloserFiltering = true;
    shadowGenerator_D.filteringQuality = BABYLON.ShadowGenerator.QUALITY_HIGH;
    shadowGenerator_D.bias = 0.001;
    shadowGenerator_D._darkness = -1.0;

    rootMesh.getChildMeshes().forEach((m) => {
      shadowGenerator_D.addShadowCaster(m);

      if (m.material && m.material.name === "robot_rigM_Screen") {
        screenMat = m.material;
      }
    });

    if (screenMat) {
      screenMat.albedoColor = BABYLON.Color3.Black();
      screenMat.emissiveColor = BABYLON.Color3.FromHexString("#343434").toLinearSpace();
    }

    const dpp = new BABYLON.DefaultRenderingPipeline("dpp", true, scene);
    dpp.imageProcessingEnabled = false;
    dpp.glowLayerEnabled = true;
  });

  function getMousePos(e) {
    return { x: e.clientX, y: e.clientY };
  }

  function moveJoint(mouse, joint, degreeLimit) {
    let degrees = getMouseDegrees(mouse.x, mouse.y, degreeLimit);
    let rotY = BABYLON.Tools.ToRadians(degrees.x);
    let rotX = BABYLON.Tools.ToRadians(degrees.y);

    let quat = BABYLON.Quaternion.RotationYawPitchRoll(rotY, rotX, 0);
    joint.rotationQuaternion = quat;
  }

  function getMouseDegrees(x, y, degreeLimit) {
    let dx = 0,
      dy = 0,
      xdiff,
      xPercentage,
      ydiff,
      yPercentage;
    let w = { x: window.innerWidth, y: window.innerHeight };

    if (x <= w.x / 2) {
      xdiff = w.x / 2 - x;
      xPercentage = (xdiff / (w.x / 2)) * 100;
      dx = ((degreeLimit * xPercentage) / 50) * -1;
    }

    if (x >= w.x / 2) {
      xdiff = x - w.x / 2;
      xPercentage = (xdiff / (w.x / 2)) * 100;
      dx = (degreeLimit * xPercentage) / 175;
    }

    if (y <= w.y / 2) {
      ydiff = w.y / 2 - y;
      yPercentage = (ydiff / (w.y / 2)) * 100;
      dy = ((degreeLimit * 0.5 * yPercentage) / 100) * -1;
    }

    if (y >= w.y / 2) {
      ydiff = y - w.y / 2;
      yPercentage = (ydiff / (w.y / 2)) * 100;
      dy = (degreeLimit * yPercentage) / 245;
    }

    return { x: dx, y: dy };
  }

  return scene;
}
